from pathlib import Path
import base64
import pandas as pd
import numpy as np

# Load data
csv_path = Path('benchmark/data.csv')
df = pd.read_csv(csv_path)

# Coerce types
for c in ['price_pence']:
    df[c] = pd.to_numeric(df[c], errors='coerce')
for c in ['recorded_at','source_updated_at']:
    df[c] = pd.to_datetime(df[c], utc=True, errors='coerce')

# Derived fields
valid_price = df[(df['price_pence']>=80) & (df['price_pence']<=250)].copy()
invalid_price_count = int(len(df) - len(valid_price))
invalid_by_fuel = df.assign(valid=(df['price_pence']>=80) & (df['price_pence']<=250)).groupby('fuel_type')['valid'].agg(['count','sum'])
invalid_by_fuel['invalid_count'] = invalid_by_fuel['count'] - invalid_by_fuel['sum']

# Price stats (valid only)
price_stats = valid_price.groupby('fuel_type')['price_pence'].agg(['count','mean','median','min','max','std'])
q = valid_price.groupby('fuel_type')['price_pence'].quantile([0.25,0.75]).unstack()
price_stats['q25']=q[0.25]
price_stats['q75']=q[0.75]
price_stats['iqr']=price_stats['q75']-price_stats['q25']
price_stats['range']=price_stats['max']-price_stats['min']

# Order for visuals
fuel_order = price_stats['median'].sort_values().index.tolist()
price_stats = price_stats.loc[fuel_order]

# Update lag
lag_hours = (df['recorded_at']-df['source_updated_at']).dt.total_seconds()/3600
neg_lag_count = int((lag_hours < 0).sum())
neg_lag_min = float(lag_hours.min())
lag_hours_pos = lag_hours.clip(lower=0)
lag_summary = lag_hours_pos.describe(percentiles=[0.5,0.9,0.95,0.99])

# Fuel-type lag median (positive-only)
lag_by_fuel_median = lag_hours_pos.groupby(df['fuel_type']).median().reindex(fuel_order)

# Station coverage
unique_stations = int(df['node_id'].nunique())
coverage_by_fuel = df.groupby('fuel_type')['node_id'].nunique().sort_values(ascending=False)
per_station_fuel_types = df.groupby('node_id')['fuel_type'].nunique()
per_station_counts = per_station_fuel_types.value_counts().sort_index()

# Latest per station freshness
latest_idx = df.sort_values('recorded_at').groupby('node_id').tail(1).index
latest = df.loc[latest_idx].copy()
latest_lag_pos = ((latest['recorded_at']-latest['source_updated_at']).dt.total_seconds()/3600).clip(lower=0)
station_lag_median = float(latest_lag_pos.median())
thresholds = [1,6,24,72,168]
station_stale_counts = {h: int((latest_lag_pos>h).sum()) for h in thresholds}
station_stale_shares = {h: float((latest_lag_pos>h).mean()) for h in thresholds}

# Date ranges
recorded_min = df['recorded_at'].min()
recorded_max = df['recorded_at'].max()
source_min = df['source_updated_at'].min()
source_max = df['source_updated_at'].max()

# Helper formatting

def fmt_ppl(x):
    return f"{x:.1f}" if pd.notna(x) else ""

def fmt_gbppl(x):
    return f"£{x/100:.3f}" if pd.notna(x) else ""

def fmt_int(x):
    return f"{int(x):,}" if pd.notna(x) else ""

def fmt_dt(x):
    if pd.isna(x):
        return ""
    return x.strftime('%Y-%m-%d %H:%M UTC')

# Load charts as data URIs

def svg_data_uri(path: Path) -> str:
    b64 = base64.b64encode(path.read_bytes()).decode('ascii')
    return f"data:image/svg+xml;base64,{b64}"

chart_paths = {
    'price_boxplot': Path('output/price_boxplot.svg'),
    'price_violin': Path('output/price_violin.svg'),
    'spread_iqr_range': Path('output/spread_iqr_range.svg'),
    'lag_hist': Path('output/lag_hist.svg'),
    'lag_by_fuel': Path('output/lag_by_fuel.svg'),
    'fuel_types_per_station': Path('output/fuel_types_per_station.svg'),
}
charts = {k: svg_data_uri(v) for k,v in chart_paths.items()}

# Build HTML tables
price_table_rows = []
for ft, row in price_stats.iterrows():
    price_table_rows.append(f"""
      <tr>
        <td><code>{ft}</code></td>
        <td class='num'>{fmt_int(row['count'])}</td>
        <td class='num'>{fmt_ppl(row['mean'])} <span class='muted'>({fmt_gbppl(row['mean'])})</span></td>
        <td class='num'>{fmt_ppl(row['median'])} <span class='muted'>({fmt_gbppl(row['median'])})</span></td>
        <td class='num'>{fmt_ppl(row['min'])}</td>
        <td class='num'>{fmt_ppl(row['max'])}</td>
        <td class='num'>{fmt_ppl(row['std'])}</td>
        <td class='num'>{fmt_ppl(row['iqr'])}</td>
        <td class='num'>{fmt_ppl(row['range'])}</td>
      </tr>
    """)

coverage_rows = []
for ft, n in coverage_by_fuel.items():
    share = n / unique_stations if unique_stations else 0
    coverage_rows.append(f"""
      <tr>
        <td><code>{ft}</code></td>
        <td class='num'>{n:,}</td>
        <td class='num'>{share:.1%}</td>
      </tr>
    """)

per_station_rows = []
for k, v in per_station_counts.items():
    per_station_rows.append(f"""
      <tr>
        <td class='num'>{int(k)}</td>
        <td class='num'>{int(v):,}</td>
        <td class='num'>{(v/unique_stations):.1%}</td>
      </tr>
    """)

stale_rows = []
for h in thresholds:
    stale_rows.append(f"""
      <tr>
        <td>{h}h</td>
        <td class='num'>{station_stale_counts[h]:,}</td>
