# Key findings (derived)
# Differences between key fuel medians
med = price_stats['median']
# Ensure presence
med_e10 = float(med.get('E10', np.nan))
med_e5 = float(med.get('E5', np.nan))
med_b7 = float(med.get('B7_STANDARD', np.nan))
med_b7p = float(med.get('B7_PREMIUM', np.nan))

findings = []
if np.isfinite(med_e5) and np.isfinite(med_e10):
    findings.append((
        f"Premium petrol <code>E5</code> is priced about <strong>{(med_e5-med_e10):.1f} p/L</strong> higher than standard petrol <code>E10</code> at the median.",
        "This median uplift provides a benchmark for assessing grade segmentation and consumer switching incentives."
    ))
if np.isfinite(med_b7) and np.isfinite(med_e10):
    findings.append((
        f"Standard diesel <code>B7_STANDARD</code> is about <strong>{(med_b7-med_e10):.1f} p/L</strong> higher than <code>E10</code> at the median.",
        "Persistent diesel premia matter for distributional impacts and could inform targeted transparency messaging."
    ))
# Dispersion highlights
# Identify highest IQR among common fuels
common = price_stats.loc[[ft for ft in price_stats.index if price_stats.loc[ft,'count']>1000]]
if len(common):
    top_iqr_ft = common['iqr'].idxmax()
    top_iqr_val = float(common.loc[top_iqr_ft,'iqr'])
    findings.append((
        f"Within-fuel price dispersion is material: <code>{top_iqr_ft}</code> shows an interquartile range of <strong>{top_iqr_val:.1f} p/L</strong> (typical middle-50% band).",
        "IQR captures the everyday spread consumers face; sustained wide IQRs can indicate limited local competitive pressure or uneven pass-through."
    ))
# Freshness finding
findings.append((
    f"Reported prices are usually fresh: the median record-level update lag is <strong>{lag_summary['50%']:.2f} hours</strong> (~{lag_summary['50%']*60:.0f} minutes).",
    "This supports the policy goal of near-real-time transparency, but tail risks still matter for consumer trust."
))
findings.append((
    f"However, a non-trivial long tail remains: in the latest observation per station, <strong>{station_stale_counts[24]:,}</strong> stations (<strong>{station_stale_shares[24]:.1%}</strong>) are more than 24 hours out of date (based on recorded vs. retailer update time).",
    "This identifies a concrete compliance/quality monitoring target: regulators can focus on repeat offenders and high-lag clusters."
))
# Data quality finding re price outliers
findings.append((
    f"Price data include <strong>{invalid_price_count:,}</strong> records (<strong>{invalid_price_count/len(df):.2%}</strong>) outside a conservative 80–250 p/L plausibility band (e.g., values near 0–1 p/L and >£10/L equivalents).",
    "These outliers can distort means/ranges and should be handled explicitly in monitoring dashboards and enforcement analytics."
))

